WITH filtered_stores AS (SELECT *, DATE_ADD(opened_date, 68) opened_date_plus_68d FROM stores WHERE city IN ('London', 'New York', 'Tokyo') AND region <> 'South' AND city IN ('New York', 'Singapore')), agg AS (SELECT city, MAX(sqft) - MIN(sqft) sqft_range, ROUND(AVG(sqft), 2) avg_sqft FROM filtered_stores GROUP BY city) SELECT city, avg_sqft FROM agg WHERE avg_sqft >= 32 ORDER BY avg_sqft DESC, city LIMIT 3;
